scripts.script:
if (args.move.weaponType === 'sword' && (args.move.type !== "basic" || args.move.id === 'opportunity-attack')) {
    args.output.damage += 5;
    args.output.bonusDesc.push('华山心法 +5');
}

if (['waigong', 'neigong'].includes(args.type)) {
    args.output.damage = Math.max(1, args.output.damage - 10);
    ui.notifications.info('抱元功抵消了 10 点伤害');
}

if (['waigong', 'neigong'].includes(args.type)) {
    args.output.damage = Math.max(1, args.output.damage - 15);
    ui.notifications.info('抱元功抵消了 15 点伤害');
}

// 检测负面状态
const s = actor.statuses;
const f = actor.xjzlStatuses;
if (f.unstable || s.has("unstable") || s.has("prone") || s.has("root") || f.forceSpeedZero || s.has("blind") || s.has("deaf")) {

    // [修复] 获取源武学 Item (通过 origin 反查)
    // thisEffect.origin 通常是 Item UUID (例如: Scene.x.Token.y.Item.z)
    const sourceItem = await fromUuid(thisEffect.origin);
    const itemId = sourceItem ? sourceItem.id : null;

    const content = `
    <div class="xjzl-chat-card" style="padding-left: 5px;">
        <div class="card-header" style="border-bottom:1px solid #ccc; margin-bottom:5px;">
            <h3 style="margin:0;">混元回血</h3>
        </div>
        <div class="card-content" style="font-size:0.9em; color:#555;">
            <p><b>触发条件满足</b></p>
            <p>处于负面状态受击。</p>
            <p>请在<b>攻击者回合结束时</b>点击：</p>
        </div>
        <div class="card-buttons">
            <button data-action="applyHeal">
                <i class="fas fa-heart"></i> 回复 20 气血
            </button>
        </div>
    </div>`;

    ChatMessage.create({
        content: content,
        speaker: ChatMessage.getSpeaker({actor: actor}),
        flags: {
            "xjzl-system": {
                actionType: "heal",
                damage: 20,
                itemId: itemId // 使用反查到的正确 ID
            }
        }
    });
    actor.showFloatyText("混元触发", { fill: "#00FFFF" });
}

if ((args.move.type === 'basic' && args.move.id !== 'opportunity-attack')) return;
const bonus = Math.floor(S.resources.mp.max * 0.1);
if (bonus > 0) {
    args.output.damage += bonus;
    args.output.bonusDesc.push(`紫极功 +${bonus}`);
}

if ((args.move.type === 'basic' && args.move.id !== 'opportunity-attack')) return;
const bonus = Math.floor(S.resources.mp.max * 0.1);
if (bonus > 0) {
    args.output.damage += bonus;
    args.output.bonusDesc.push(`紫极功 +${bonus}`);
}

if (args.isHit && args.isAttack) {
    // 自身回复
    await args.attacker.applyHealing({ healer: actor, amount: 5, type: 'mp'});
    // 敌方流失
    const tMp = args.target.system.resources.mp.value;
    if (tMp > 0) {
        await args.target.changeResources({"system.resources.mp.value": Math.max(0, tMp - 5)}, { cause: "script", sourceActor: actor, target: args.target, item: thisItem instanceof Item ? thisItem : (args.item || null), move: typeof move !== "undefined" ? move : (args.move || null) });
        actor.showFloatyText(`${args.target.name} 流失内力`, {fill: "#0000FF"});
    }
}

if ((args.move.type === 'basic' && args.move.id !== 'opportunity-attack')) return;
const bonus = Math.floor(S.resources.mp.max * 0.1);
if (bonus > 0) {
    args.output.damage += bonus;
    args.output.bonusDesc.push(`紫极功 +${bonus}`);
}

if (args.isHit && args.isAttack) {
    // 自身回复
    await args.attacker.applyHealing({ healer: actor, amount: 10, type: 'mp'});
    // 敌方流失
    const tMp = args.target.system.resources.mp.value;
    if (tMp > 0) {
        await args.target.changeResources({"system.resources.mp.value": Math.max(0, tMp - 10)}, { cause: "script", sourceActor: actor, target: args.target, item: thisItem instanceof Item ? thisItem : (args.item || null), move: typeof move !== "undefined" ? move : (args.move || null) });
        actor.showFloatyText(`${args.target.name} 流失内力`, {fill: "#0000FF"});
    }
}
